// @archon-test-isolated
/**
 * `archon workflow types`: which nodes a target's generated file holds, and what
 * check mode reports. The converter's own cases live in output-types/schema-to-ts.test.ts.
 */
import { providerRegistry } from '@archon/providers';
import { afterEach, beforeEach, describe, expect, test } from 'bun:test';
import { mkdir, mkdtemp, readFile, realpath, writeFile } from 'fs/promises';
import { tmpdir } from 'os';
import { join } from 'path';
import { trackTempRoots } from '@archon/paths/test-utils';
import { generateOutputTypes, type OutputTypesOptions } from './output-types';

const trackTempRoot = trackTempRoots();
const originalArchonHome = process.env.ARCHON_HOME;
let cwd: string;

beforeEach(async () => {
  cwd = trackTempRoot(await realpath(await mkdtemp(join(tmpdir(), 'output-types-'))));
  process.env.ARCHON_HOME = join(cwd, 'home');
});

afterEach(() => {
  if (originalArchonHome === undefined) delete process.env.ARCHON_HOME;
  else process.env.ARCHON_HOME = originalArchonHome;
});

const BLOCK = `name: block
description: d
nodes:
  - id: verdict
    bash: echo '{"ok":true}'
    output_format:
      type: object
      properties:
        ok: { type: boolean }
        rank: { type: string, enum: [low, high] }
      required: [ok]
`;

const MAIN = `name: main
description: d
nodes:
  - id: plain
    bash: echo hi
  - id: route
    bash: echo '{"decision":"go"}'
    output_format:
      type: object
      additionalProperties: false
      properties:
        decision: { type: string, enum: [go, stop] }
      required: [decision]
  - id: shared
    include: block
    depends_on: [route]
  - id: rounds
    depends_on: [shared]
    loop_group:
      until_bash: 'true'
      max_iterations: 2
      nodes:
        - id: inner
          bash: echo '{"n":1}'
          output_format:
            type: object
            properties:
              n: { type: [integer, 'null'] }
            required: [n]
`;

async function writePackWorkflow(pack: string, folder: string, yaml: string): Promise<string> {
  const dir = join(cwd, '.archon', 'workflows', pack, folder);
  await mkdir(dir, { recursive: true });
  const file = join(dir, `${folder}.yaml`);
  await writeFile(file, yaml);
  return file;
}

const packFile = (pack: string): string =>
  join(cwd, '.archon', 'workflows', pack, '.shared', 'outputs.generated.ts');

const generate = (options: Partial<OutputTypesOptions> & { target: string }) =>
  generateOutputTypes({ cwd, check: false, providers: providerRegistry, ...options });

describe('generateOutputTypes', () => {
  test('a pack writes one file: each node under the workflow that declares it', async () => {
    await writePackWorkflow('alpha', 'main', MAIN);
    await writePackWorkflow('alpha', 'block', BLOCK);

    const result = await generate({ target: 'alpha' });

    expect(result).toEqual({ path: packFile('alpha'), status: 'written', workflows: 2, nodes: 3 });
    expect(
      await readFile(packFile('alpha'), 'utf-8')
    ).toBe(`// Generated by \`archon workflow types alpha\` from each node's output_format. Do not edit.
// Change the workflow YAML and rerun the command; with --check it fails while this file is stale.

/** Each workflow's node outputs, as the node's \`output_format\` declares them. */
export interface WorkflowOutputs {
  block: {
    verdict: {
      readonly ok: boolean;
      readonly rank?: 'low' | 'high';
    };
  };
  main: {
    route: {
      readonly decision: 'go' | 'stop';
    };
    inner: {
      readonly n: number | null;
    };
  };
}

/** One node's output, for example \`NodeOutput<'block', 'verdict'>\`. */
export type NodeOutput<
  W extends keyof WorkflowOutputs,
  N extends keyof WorkflowOutputs[W],
> = WorkflowOutputs[W][N];

/**
 * The values of every \`enum\` in those schemas, by workflow, node and schema path:
 * \`.\` enters a property, \`[]\` an array's items, \`anyOf[n]\` an alternative, and \`$\`
 * is the schema itself.
 */
export const OUTPUT_ENUMS = {
  block: {
    verdict: {
      rank: ['low', 'high'],
    },
  },
  main: {
    route: {
      decision: ['go', 'stop'],
    },
  },
} as const;
`);
  });

  test('a pack directory path resolves from the invoking directory', async () => {
    await writePackWorkflow('alpha', 'block', BLOCK);

    const result = await generate({
      target: './workflows/alpha',
      targetCwd: join(cwd, '.archon'),
    });

    expect(result).toMatchObject({ path: packFile('alpha'), status: 'written' });
  });

  test('check writes nothing: missing and edited files are stale, a fresh one is current', async () => {
    const file = await writePackWorkflow('alpha', 'block', BLOCK);

    expect((await generate({ target: 'alpha', check: true })).status).toBe('stale');
    expect(await Bun.file(packFile('alpha')).exists()).toBe(false);

    await generate({ target: 'alpha' });
    expect((await generate({ target: 'alpha', check: true })).status).toBe('current');
    expect((await generate({ target: 'alpha' })).status).toBe('unchanged');

    // A checkout that converted the committed file to CRLF is still current.
    const generated = await readFile(packFile('alpha'), 'utf-8');
    await writeFile(packFile('alpha'), generated.replaceAll('\n', '\r\n'));
    expect((await generate({ target: 'alpha', check: true })).status).toBe('current');
    await writeFile(packFile('alpha'), generated);

    await writeFile(file, BLOCK.replace('[low, high]', '[low, mid, high]'));
    const before = await readFile(packFile('alpha'), 'utf-8');
    expect(await generate({ target: 'alpha', check: true })).toMatchObject({
      path: packFile('alpha'),
      status: 'stale',
    });
    expect(await readFile(packFile('alpha'), 'utf-8')).toBe(before);
  });

  test('one workflow, by name or by file, needs --out and holds only its own nodes', async () => {
    await writePackWorkflow('alpha', 'main', MAIN);
    const blockFile = await writePackWorkflow('alpha', 'block', BLOCK);
    await writeFile(
      join(cwd, '.archon', 'workflows', 'flat.yaml'),
      BLOCK.replace('name: block', 'name: flat')
    );

    await expect(generate({ target: 'flat' })).rejects.toThrow('Pass --out <file>');

    const byName = await generate({ target: 'flat', out: 'types/flat.gen.ts' });
    expect(byName).toEqual({
      path: join(cwd, 'types', 'flat.gen.ts'),
      status: 'written',
      workflows: 1,
      nodes: 1,
    });
    const content = await readFile(byName.path, 'utf-8');
    expect(content).toContain('`archon workflow types flat --out <file>`');
    expect(content).toContain('  flat: {\n    verdict: {');
    expect(content).not.toContain('main');

    const byFile = await generate({ target: blockFile, out: 'block.gen.ts' });
    expect(byFile).toMatchObject({ workflows: 1, nodes: 1 });
    expect(await readFile(byFile.path, 'utf-8')).toContain('  block: {\n    verdict: {');
  });

  test('an unsupported keyword fails naming the workflow, the node and the keyword', async () => {
    await writePackWorkflow(
      'alpha',
      'block',
      BLOCK.replace('ok: { type: boolean }', 'ok: { allOf: [{ type: boolean }] }')
    );

    await expect(generate({ target: 'alpha' })).rejects.toThrow(
      "Workflow 'block', node 'verdict': output_format keyword 'allOf' at 'ok': is not supported."
    );
    expect(await Bun.file(packFile('alpha')).exists()).toBe(false);
  });

  test('a pack with a workflow that does not load is refused, not generated in part', async () => {
    await writePackWorkflow('alpha', 'block', BLOCK);
    await writePackWorkflow('alpha', 'broken', 'name: broken\nnodes: []\n');

    await expect(generate({ target: 'alpha' })).rejects.toThrow(
      "Pack 'alpha' has workflows that do not load"
    );
  });

  test('a target that names nothing, and one with no output_format, are errors', async () => {
    await writePackWorkflow(
      'alpha',
      'bare',
      'name: bare\ndescription: d\nnodes:\n  - id: a\n    bash: echo hi\n'
    );

    await expect(generate({ target: 'missing' })).rejects.toThrow("No pack or workflow 'missing'");
    await expect(generate({ target: './nowhere' })).rejects.toThrow(
      "No file or directory at './nowhere'"
    );
    await expect(generate({ target: 'alpha' })).rejects.toThrow(
      'No node declares an output_format'
    );
  });
});
